-- MSC Articleship Program v3 (course msc-articleship-program), release 2. Generated by msc-content/articleship-program/v3/build/lms/build_lms_sql.mjs
-- --release-2 from lms-rows.json (with its "release_2" block) and build/release/release-2/files.json; do not edit by hand.
-- Rows follow V3-STRUCTURE section 2 (one session per Day, Day 0 to Day 6) with Padam's B9 sheets, now with row 1.6.
-- Files live in bucket industrial-training-mastery-resources under articleship-program-v3/.
--
-- 005 · Release 2, the Work Simulation. What it does:
--   - adds row 1.6 "Work Simulation" to Day 1 under its own heading "Work Simulation",
--     between "Pick your design" and "Check your CV": a tool row (external_link) opening
--     /articleship-program/work-simulation/ (a relative path: the site the course page is on);
--   - gives Day 1 the description that names it ("Done when: …; one Work Simulation level is done; …");
--   - keeps every other row as it is: the release-1 rows; a later row (003) once all its files are in the bucket; the
--     Automail row only if 004 has added it (this file never adds it).
-- Order: (1) upload the 18 files in upload-release-2/ to bucket industrial-training-mastery-resources at the same
--     paths (each replaces its release-1 copy; upload-release-2-manifest.csv); (2) merge both pull requests
--     (WORK_SIMULATION_LIVE = true); (3) run this file.
-- Guards (each stops the whole file, changing nothing): 002 has not run; a release-2 file is not in the bucket, or is
-- still its release-1 copy (its size in storage.objects differs from the manifest's bytes).
-- Safe to run again and again: each run writes the whole course in its final order (running it again does what the
-- release-2 003 does). From release 2 on, 003 and 004 are their release-2 versions (this handover's migrations/, the
-- same names): run them after this file for later uploads and for the Automail row; both keep row 1.6.
-- Never touches recordings (industrial_training_path), enrolment, schema or storage.
-- Undo: run release 1's 003 again (release 1's 004 if the Automail row is live; both in the release-1 handover
-- 2026-10-20-articleship-program-v3/migrations/): they write the course without row 1.6 and with the release-1 Day 1
-- description. Or run 002, then release 1's 003/004, to go back to release 1 itself. Then upload the release-1 copies
-- of the files above again (upload-release-1/, and upload-004/ if 004 has run), so the PDFs hide the Work Simulation
-- again.
BEGIN;

DO $guard$
BEGIN
    IF EXISTS (SELECT 1 FROM public.videos WHERE course = 'msc-articleship-program' AND video_number BETWEEN 8 AND 13) THEN
        RAISE EXCEPTION 'Run 002_articleship_program_v3_lms.sql first: the v2 sessions 8-13 are still there.';
    END IF;
    IF (SELECT count(*) FROM public.videos WHERE course = 'msc-articleship-program' AND video_number BETWEEN 1 AND 7) <> 7 THEN
        RAISE EXCEPTION 'Run 002_articleship_program_v3_lms.sql first: sessions 1-7 are not all there.';
    END IF;
END
$guard$;

DO $uploads$
DECLARE
    waiting text;
BEGIN
    SELECT string_agg(p.path || CASE WHEN o.name IS NULL THEN ' (not in the bucket)'
                                     ELSE ' (still the release-1 copy: ' || (o.metadata ->> 'size') || ' bytes; the release-2 file has ' || p.bytes || ')' END,
                      E'\n' ORDER BY p.path) INTO waiting
    FROM (VALUES
        ('articleship-program-v3/day-0/MSC Articleship Guidebook.pdf', 6046934),
        ('articleship-program-v3/day-1/Choose your CV.pdf', 2584404),
        ('articleship-program-v3/day-1/The Nothing CV.pdf', 1117761),
        ('articleship-program-v3/day-1/CV templates.pdf', 9320378),
        ('articleship-program-v3/day-1/Keywords by domain.pdf', 1509651),
        ('articleship-program-v3/day-1/Cover letters.pdf', 1020524),
        ('articleship-program-v3/day-1/Cover letters.docx', 15213),
        ('articleship-program-v3/day-2/Big 10 articleship routes.pdf', 333251),
        ('articleship-program-v3/day-2/Application templates.pdf', 1574845),
        ('articleship-program-v3/day-2/Follow-up templates.pdf', 1304666),
        ('articleship-program-v3/day-2/Back-out templates.pdf', 983305),
        ('articleship-program-v3/day-3/LinkedIn search links.pdf', 895067),
        ('articleship-program-v3/day-3/First message after the request is accepted.pdf', 784639),
        ('articleship-program-v3/day-3/Follow-up messages.pdf', 949637),
        ('articleship-program-v3/day-6/Articleship registration process.pdf', 431246),
        ('articleship-program-v3/day-6/Articleship transfer guidelines.pdf', 219323),
        ('articleship-program-v3/day-6/Industrial training guide.pdf', 269402),
        ('articleship-program-v3/day-6/CA Final study guidelines.pdf', 184542)
    ) AS p(path, bytes)
    LEFT JOIN storage.objects AS o ON o.bucket_id = 'industrial-training-mastery-resources' AND o.name = p.path
    WHERE o.name IS NULL
       OR ((o.metadata ->> 'size') IS NOT NULL AND (o.metadata ->> 'size')::bigint <> p.bytes);
    IF waiting IS NOT NULL THEN
        RAISE EXCEPTION 'Upload the release-2 files to bucket industrial-training-mastery-resources first (upload-release-2/, same paths; nothing was changed):%', E'\n' || waiting;
    END IF;
END
$uploads$;

